"""
QuantX — Base Strategy Architecture.

Defines the Signal payload structure and the Abstract Base Strategy class.
All quantitative strategies inherit from BaseStrategy.
"""

from abc import ABC, abstractmethod
from datetime import UTC, datetime
from typing import Any, Literal

from pydantic import BaseModel, Field


class Signal(BaseModel):
    """Trading signal payload generated by strategies or the AI agent."""

    action: Literal["BUY", "SELL", "WAIT"]
    symbol: str
    timeframe: str
    confidence: float = Field(..., ge=0.0, le=1.0, description="Signal confidence score 0.0 to 1.0")
    reasoning: str
    timestamp: datetime = Field(default_factory=lambda: datetime.now(UTC))
    entry_price: float | None = None
    stop_loss: float | None = None
    take_profit: float | None = None
    metadata: dict[str, Any] = Field(default_factory=dict)


class BaseStrategy(ABC):
    """Abstract Base Class for quantitative trading strategies."""

    name: str = "base_strategy"
    description: str = "Abstract base strategy"

    # Number of trailing rows generate_signal needs. The backtester slices
    # exactly this many rows per step; without it the engine has to hand over
    # the whole history every bar, which makes a backtest quadratic.
    lookback: int = 2

    @abstractmethod
    def generate_signal(self, symbol: str, timeframe: str, df_indicators: Any) -> Signal:
        """Evaluate market data and return a trading signal.

        Args:
            symbol: Trading symbol (e.g. BTCUSDT)
            timeframe: Timeframe (e.g. 1h)
            df_indicators: DataFrame containing OHLCV + technical indicators

        Returns:
            Signal object with action (BUY/SELL/WAIT), confidence, and reasoning.
        """
        pass
